	Say("飞龙堡总管卢肇灏：弟兄们，上啊，这小子杀了我们这么多人，大家把他剁成肉酱，为死了的弟兄们报仇。", 46);
	Say("杨影枫：（怎么不分青红皂白就要打？）慢着，我问你们，你们把纳兰真小姐藏到哪里去了？", 6);
	Say("卢肇灏：少罗嗦，大家上啊！", 46);
	EnableNpcAI();
	Assign($Event99FightNo, 0);
	
	SetMapTrap(1, "");
	SetMapTrap(2, "");
	
