	EnableNpcAI();
	SetMapTrap(1,"trap01.txt");
	FadeIn();
	Return;

traps.事件97_1.txt:
	If ($Event == 960) @Label1;
	
	Goto @end;
	
@Label1:
	If ($Result <> 3) @end;
	
	PlayerGoto(29, 89);
	SetPlayerDir(5);
	Say("杨影枫：这里有人。", 4);
	MoveScreen(5, 100, 1);
	Say("纳兰潜凛：唉，姑娘，你何不从了我无忧教，大家一起在武林中干一番事业，惟我独尊，岂不是好？", 41);
	Say("月眉儿：嘿嘿，你趁我外出之际，伤我飞龙堡门下众多子弟，这笔帐咱们如何了结？", 26);
	Say("纳兰潜凛：唉，姑娘如若及早听从我的劝告，率飞龙堡归顺我无忧教，又如何会发生这些伤和气的事情呢？！", 41);
	Say("月眉儿：要我归顺你，原也容易，只是没见识一下你手底下的真章，嘿嘿，我门下弟兄们自由自在惯了，怕是不服。", 26);
	Say("纳兰潜凛：说来说去，还是要手底下见真章了。我本也不想授人以柄，说我以大欺小，既然姑娘这么说，那我就不客气了！", 41);
	Say("月眉儿：哼，阁下又何必惺惺作态呢？你什么时候客气过？", 26);
	Say("纳兰潜凛：好个伶牙俐齿的小丫头！姑娘好生面熟，敢问姑娘何方人氏？", 38);
	Say("月眉儿：笑话！本姑娘的资历为何要说与你知？少罗嗦，动手吧！", 26);
	Say("纳兰潜凛：你以为我不敢下杀手吗？！", 41);
	Say("月眉儿：难道我会怕你这个老魔头吗？", 26);

	DisableInput();
	SetNpcKind("杨影枫", 0);
	NpcGotoEx("月眉儿", 34, 80);
	NpcGoto("纳兰潜凛", 34, 81);
	SetNpcDir("月眉儿", 7);
	SetNpcDir("纳兰潜凛", 3);
	SetNpcRelation("月眉儿", 0);
	SetNpcRelation("纳兰潜凛", 1);
	Assign($Event, 962);

	Goto @end;
	
@end:
	Return;
